export type TerminalSession = {
  paused?: boolean;
  suspended?: boolean;
  loading?: Sprite[];
  saving?: boolean;
  saveName?: string;
  selection?: number;
  failed?: boolean;
  flipped?: boolean;
};

export const getTerminalLayout = (columns: number, rows: number) => {
  const width = Math.min(columns, 33);
  const height = Math.min(maxWorldRows, Math.max(1, rows - 7));
  return {
    width,
    height,
    left: Math.floor((columns - width) / 2),
    top: 4 + Math.floor((rows - 7 - height) / 2),
  };
};

export const getPauseActions = (world: World, saving = false) => [
  { name: "RESUME", palette: "lime" as const, disabled: false },
  ...(world.metadata.gameEntity[LEVEL].name === "LEVEL_MENU"
    ? []
    : [
        { name: "MENU", palette: "red" as const, disabled: false },
        { name: saving ? "SAVING" : "SAVE", palette: "white" as const, disabled: saving || !canSave(world) },
      ]),
];

export const getTerminalFrame = (
  world: World,
  columns: number,
  rows: number,
  state?: TerminalState,
  session: TerminalSession = {}
) => {
  const { width, height, left, top } = getTerminalLayout(columns, rows);
  const hero = world.getEntities([PLAYER])[0];
  let scene = session.suspended
    ? []
    : getSceneFrame(world, width, height, state, {
        instant: true,
        fogCells: true,
      });
  const popup = world.getEntityByIdAndComponents(hero?.[PLAYER].popup, [POPUP]);
  const sequence = popup && getSequence(world, popup, "popup");
  if (popup && sequence) {
    const index = popup[POPUP].horizontalIndex;
    const tabs = sequence.args.instant
      ? [popup[POPUP].tabs[index]]
      : popup[POPUP].tabs;
    const selected = sequence.args.instant ? 0 : index;
    const tabCount = tabs.length;
    const mapFog = [mapZoom1, mapZoom2, mapZoom3, mapZoom4][
      popup[POPUP].verticalIndezes[index] || 0
    ];
    for (const entry of scene) {
      if (
        entry.particleName?.startsWith("popup-content-") &&
        tabs[selected] === "map" &&
        entry.layers.every(
          (layer) =>
            " █▀▄▌▐░▒▓".includes(layer.char) ||
            mapFog?.layers.some(
              (fog) => fog.char === layer.char && fog.color === layer.color
            )
        )
      ) {
        const pixel = projectLayers(entry.layers, "map_pixel");
        entry.terminalLayers = [
          { char: "█", color: pixel.background! },
          { char: pixel.char, color: pixel.foreground },
        ];
      }
      if (
        entry.particle ===
        world.getEntityById(sequence.particles["popup-close-1"])
      ) {
        const sprite = createText("X", colors.black, colors.red)[0];
        entry.sprite = sprite;
        entry.layers = sprite.layers;
      }
      const tabCell = Array.from(
        { length: tabCount * 6 + 1 },
        (_, i) => i
      ).find(
        (i) =>
          entry.particle ===
          world.getEntityById(sequence.particles[`popup-tab-${i}`])
      );
      if (tabCell === undefined) continue;
      const boundary = tabCell % 6 === 0;
      const tab = Math.min(Math.floor(tabCell / 6), tabCount - 1);
      const active = boundary
        ? tabCell === selected * 6 || tabCell === (selected + 1) * 6
        : tab === selected;
      const char = boundary
        ? tabCell === 0 || tabCell === selected * 6
          ? "["
          : tabCell === tabCount * 6 || tabCell === (selected + 1) * 6
          ? "]"
          : "|"
        : padCenter(popupTitles[tabs[tab]], 5)[(tabCell % 6) - 1];
      const foreground = active
        ? colors.black
        : sequence.args.instant
        ? colors.yellow
        : colors.white;
      const background = active
        ? sequence.args.instant
          ? colors.yellow
          : colors.white
        : sequence.args.instant
        ? colors.olive
        : colors.grey;
      const sprite = createText(char, foreground, background)[0];
      entry.sprite = sprite;
      entry.layers = sprite.layers;
      entry.terminalLayers = sprite.layers;
    }
  }
  const sprites: TerminalSprite[] = collectTerminalSprites(scene)
    .map((sprite) => ({
      ...sprite,
      x: Math.ceil(sprite.x),
      y: Math.ceil(sprite.y),
    }))
    .filter(
      (sprite) =>
        sprite.x >= 0 && sprite.x < width && sprite.y >= 0 && sprite.y < height
    )
    .map((sprite) => ({ ...sprite, x: sprite.x + left, y: sprite.y + top }));
  const line = (
    cells: Sprite[],
    y: number,
    x = Math.floor((columns - cells.length) / 2),
    z = 1000
  ) => {
    cells.forEach((sprite, index) =>
      sprites.push({
        x: x + index,
        y,
        z,
        sprite,
        layers: sprite.layers,
        terminalLayers: sprite.terminal?.layers,
      })
    );
  };
  const progress = (
    stats: Parameters<typeof createProgress>[0],
    stat: "hp" | "mp" | "xp",
    depletable = true
  ) =>
    createProgress(stats, stat, 13, depletable).map((sprite) =>
      customSprite({
        ...sprite,
        terminal: {
          layers: sprite.terminal!.layers.map((layer) =>
            layer.char === "░" ? { char: "█", color: colors.black } : layer
          ),
        },
      })
    );
  if (hero) {
    const pauseButton = createSpriteButton(
      [session.paused ? pauseInvertPressed : pauseInvert],
      3,
      false,
      !!session.paused
    );
    if (!TEST_MODE && world.metadata.gameEntity[LEVEL].name === "LEVEL_MENU") {
      line(
        pauseButton,
        top - 2,
        Math.floor((columns - 21) / 2) + (session.flipped ? 18 : 0)
      );
    } else {
      const stats = getEntityStats(world, hero);
      const progressLeft =
        Math.floor((columns - 21) / 2) + (session.flipped ? 5 : 3);
      line(progress(stats, "hp", false), top - 4, progressLeft);
      line(progress(stats, "mp"), top - 3, progressLeft);
      const useButton = createSpriteButton(
        [
          ...createText("US", colors.black),
          ...underline(createText("E", colors.black), colors.black),
        ],
        5,
        !!session.paused,
        false,
        false,
        "yellow"
      );
      line(
        session.flipped
          ? [...useButton, ...progress(stats, "xp"), ...pauseButton]
          : [...pauseButton, ...progress(stats, "xp"), ...useButton],
        top - 2
      );
      const action = (slot: "spell" | "skill" | "tool", fallback: string) => {
        const entity = world.getEntityByIdAndComponents(
          hero[ACTIONABLE]?.[slot],
          [ITEM, SPRITE]
        );
        const available =
          !!entity &&
          !!hero[INVENTORY] &&
          !!hero[POSITION] &&
          isInteractable(world, hero) &&
          (slot === "spell"
            ? canCast(world, hero, entity) &&
              castableSpell(world, hero as TypedEntity<"INVENTORY">, entity)
            : castableSkill(
                world,
                hero as TypedEntity<"INVENTORY" | "POSITION">,
                entity
              ));
        return {
          button: createButton(
            entity ? getActionName(world, hero, entity) : fallback,
            7,
            !available || !!session.paused,
            false,
            false,
            entity ? "silver" : "white"
          ),
          activation: centerSprites(
            entity
              ? getActionActivations(
                  world,
                  hero as TypedEntity,
                  entity[ITEM],
                  slot !== "spell"
                )
              : [],
            7
          ),
        };
      };
      const skill = action(
        hero[ACTIONABLE]?.toolEquipped || !hero[EQUIPPABLE]?.skill
          ? "tool"
          : "skill",
        "^S"
      );
      const spell = action("spell", "SPACE");
      const compass = world.getEntityByIdAndComponents(
        hero[EQUIPPABLE]?.compass,
        [ITEM]
      );
      const equipment = compass
        ? [
            getItemSprite(
              compass[ITEM],
              "display",
              compass[ORIENTABLE]?.facing
            ),
            ...createText("Compass", colors.grey),
          ]
        : repeat(none, 8);
      line(
        session.flipped
          ? [...equipment, none, ...spell.button, ...skill.button]
          : [...skill.button, ...spell.button, none, ...equipment],
        top + height + 1
      );
      line(
        session.flipped
          ? [...repeat(none, 9), ...spell.activation, ...skill.activation]
          : [...skill.activation, ...spell.activation, ...repeat(none, 9)],
        top + height + 2
      );
    }
  }
  // The game keeps its own maximum viewport inside the full terminal chrome.
  for (let y = top; y < top + height; y++) {
    line(createText("│", colors.silver), y, left, popupHeight - 0.0005);
    line(
      createText("│", colors.silver),
      y,
      left + width - 1,
      popupHeight - 0.0005
    );
  }
  line(
    createText("┌" + "─".repeat(width - 2) + "┐", colors.silver),
    top - 1,
    left,
    popupHeight - 0.0005
  );
  line(
    createText("└" + "─".repeat(width - 2) + "┘", colors.silver),
    top + height,
    left,
    popupHeight - 0.0005
  );
  if (session.suspended) {
    const loading = session.loading ??
      worldLoading(levelConfig[world.metadata.gameEntity[LEVEL].name].name);
    line(
      loading,
      top + Math.floor(height / 2) - 1,
      left + Math.floor(width / 2) - Math.floor((loading.length - 1) / 2)
    );
  } else if (session.paused) {
    const background = createTerminalFrame(sprites, columns, rows);
    const fogged = new Set(
      sprites
        .filter((sprite) => sprite.fog)
        .map((sprite) => sprite.y * columns + sprite.x)
    );
    for (let y = top; y < top + height; y++)
      line(
        background[y]
          .slice(left + 1, left + width - 1)
          .flatMap((cell, x) =>
            createText(
              "░",
              fogged.has(y * columns + left + 1 + x) &&
                cell.background === colors.grey &&
                cell.char !== " " &&
                orderedColors.includes(cell.foreground) &&
                ![
                  colors.black,
                  colors.grey,
                  colors.silver,
                  colors.white,
                ].includes(cell.foreground)
                ? cell.foreground
                : cell.background && cell.background !== colors.black
                ? cell.background
                : cell.char === " "
                ? colors.black
                : cell.foreground,
              colors.black
            )
          ),
        y,
        left + 1,
        2000
      );
    const actions = getPauseActions(world, session.saving);
    const overlay: Sprite[][] = [
      createText("█▀▄ █▀▄ █ █ ▄▀▀ ▄▀▀"),
      createText("█▄█ █▄█ █ █ █▄▄ █▄▄"),
      createText("█   █ █ █▄▀ ▄▄▀ █▄▄"),
      [],
      [],
    ];
    actions.forEach((action, index) => {
      if (index) overlay.push([]);
      const selected = (session.selection || 0) === index && !action.disabled;
      overlay.push([
        ...createText(selected ? ">" : " "),
        ...createSpriteButton(
          createText(action.name, buttonPalettes[action.palette].text),
          8,
          action.disabled || !selected,
          false,
          selected,
          action.palette
        ),
      ]);
    });
    if (actions.length > 1)
      overlay.push(
        createText(
          session.saving ? "" : session.failed ? "Failed!" : session.saveName || "",
          session.failed ? colors.red : colors.grey
        )
      );
    const overlayWidth = Math.max(...overlay.map((row) => row.length));
    const offset = top + Math.ceil((height - overlay.length) / 2);
    overlay.forEach((row, y) =>
      line(
        addBackground(row, colors.black),
        offset + y,
        Math.floor((columns - overlayWidth) / 2) +
          Math.floor((overlayWidth - row.length) / 2),
        3000
      )
    );
  }
  const frame = createTerminalFrame(sprites, columns, rows);
  return !session.paused && !session.suspended
    ? shakeTerminalFrame(world, frame, state)
    : frame;
};
